// aim.cpp - in-engine aim assist math: projects entity head positions to
// screen space and returns a smoothed crosshair delta toward the best target
// inside a circular screen-space cone (default 240px radius).
//
// Pure computation over data supplied by the game itself (view-projection
// matrix, entity list, viewport). Intended to be called from the game's own
// input/camera update.

#include <cmath>
#include <cstddef>
#include <cstdint>
#include <limits>

namespace aim {

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };

// Row-major 4x4 view-projection matrix, row-vector convention (D3D style):
// clip = [x y z 1] * M
struct Mat4 { float m[4][4]; };

struct Entity {
    Vec3     head;      // world-space head position
    uint32_t team;      // team id
    bool     alive;
    bool     visible;   // result of the game's own line-of-sight test
};

struct Viewport {
    int width;
    int height;
};

struct Config {
    float    coneRadiusPx   = 240.0f; // screen-space acquisition radius
    float    smoothRate     = 12.0f;  // higher = snappier (1/s)
    float    maxStepPx      = 40.0f;  // per-frame delta clamp
    uint32_t localTeam      = 0;
    bool     requireVisible = true;
};

// Projects a world-space point to pixel coordinates. Returns false if the
// point is behind the camera or outside the clip volume.
bool WorldToScreen(const Mat4& vp, const Vec3& p, const Viewport& view, Vec2* out)
{
    const float cx = p.x * vp.m[0][0] + p.y * vp.m[1][0] + p.z * vp.m[2][0] + vp.m[3][0];
    const float cy = p.x * vp.m[0][1] + p.y * vp.m[1][1] + p.z * vp.m[2][1] + vp.m[3][1];
    const float cz = p.x * vp.m[0][2] + p.y * vp.m[1][2] + p.z * vp.m[2][2] + vp.m[3][2];
    const float cw = p.x * vp.m[0][3] + p.y * vp.m[1][3] + p.z * vp.m[2][3] + vp.m[3][3];

    if (cw < 1e-3f)
        return false;

    const float inv = 1.0f / cw;
    const float nx = cx * inv;
    const float ny = cy * inv;
    const float nz = cz * inv;

    if (nx < -1.0f || nx > 1.0f || ny < -1.0f || ny > 1.0f || nz < 0.0f || nz > 1.0f)
        return false;

    out->x = (nx + 1.0f) * 0.5f * static_cast<float>(view.width);
    out->y = (1.0f - ny) * 0.5f * static_cast<float>(view.height);
    return true;
}

// Finds the entity whose projected head is closest to screen centre and
// inside the cone. Returns its index, or -1 if none qualifies.
int SelectTarget(const Mat4& vp, const Entity* ents, size_t count,
                 const Viewport& view, const Config& cfg, Vec2* outScreen)
{
    const float centerX = static_cast<float>(view.width)  * 0.5f;
    const float centerY = static_cast<float>(view.height) * 0.5f;
    const float r2 = cfg.coneRadiusPx * cfg.coneRadiusPx;

    int   best   = -1;
    float bestD2 = std::numeric_limits<float>::max();
    Vec2  bestPt = { centerX, centerY };

    for (size_t i = 0; i < count; ++i) {
        const Entity& e = ents[i];
        if (!e.alive || e.team == cfg.localTeam)
            continue;
        if (cfg.requireVisible && !e.visible)
            continue;

        Vec2 s;
        if (!WorldToScreen(vp, e.head, view, &s))
            continue;

        const float dx = s.x - centerX;
        const float dy = s.y - centerY;
        const float d2 = dx * dx + dy * dy;
        if (d2 <= r2 && d2 < bestD2) {
            bestD2 = d2;
            best   = static_cast<int>(i);
            bestPt = s;
        }
    }

    if (outScreen)
        *outScreen = bestPt;
    return best;
}

// Stateful smoother: frame-rate-independent exponential approach toward the
// selected target, with a per-frame magnitude clamp.
class AimAssist {
public:
    explicit AimAssist(const Config& cfg = Config()) : cfg_(cfg) {}

    void SetConfig(const Config& cfg) { cfg_ = cfg; }
    void Reset() { lastTarget_ = -1; }

    // Returns true and writes the crosshair delta (pixels) if a target is
    // inside the cone; otherwise writes {0,0} and returns false.
    bool Update(const Mat4& vp, const Entity* ents, size_t count,
                const Viewport& view, float dtSeconds, Vec2* outDelta)
    {
        outDelta->x = 0.0f;
        outDelta->y = 0.0f;

        Vec2 target;
        const int idx = SelectTarget(vp, ents, count, view, cfg_, &target);
        if (idx < 0) {
            lastTarget_ = -1;
            return false;
        }
        lastTarget_ = idx;

        const float rawX = target.x - static_cast<float>(view.width)  * 0.5f;
        const float rawY = target.y - static_cast<float>(view.height) * 0.5f;

        const float dt    = dtSeconds > 0.0f ? dtSeconds : 0.0f;
        const float alpha = 1.0f - std::exp(-cfg_.smoothRate * dt);

        float dx = rawX * alpha;
        float dy = rawY * alpha;

        const float mag = std::sqrt(dx * dx + dy * dy);
        if (mag > cfg_.maxStepPx && mag > 0.0f) {
            const float s = cfg_.maxStepPx / mag;
            dx *= s;
            dy *= s;
        }

        outDelta->x = dx;
        outDelta->y = dy;
        return true;
    }

    int LastTarget() const { return lastTarget_; }

private:
    Config cfg_;
    int    lastTarget_ = -1;
};

} // namespace aim

#ifdef AIM_SMOKE
#include <cstdio>

int main()
{
    using namespace aim;

    // Simple perspective (fov 90, aspect 16:9, near 0.1, far 1000), camera at
    // origin looking down +Z; identity view.
    const float aspect = 1920.0f / 1080.0f;
    const float f      = 1.0f; // 1/tan(45deg)
    const float zn = 0.1f, zf = 1000.0f;
    Mat4 vp = {};
    vp.m[0][0] = f / aspect;
    vp.m[1][1] = f;
    vp.m[2][2] = zf / (zf - zn);
    vp.m[2][3] = 1.0f;
    vp.m[3][2] = -zn * zf / (zf - zn);

    Entity ents[] = {
        { { 1.0f,  0.5f, 10.0f }, 2, true, true },  // near centre
        { { 8.0f,  0.0f, 10.0f }, 2, true, true },  // outside cone
        { { 0.2f,  0.1f, 10.0f }, 1, true, true },  // teammate
    };

    Viewport view = { 1920, 1080 };
    Config cfg;
    cfg.localTeam = 1;
    AimAssist assist(cfg);

    for (int frame = 0; frame < 5; ++frame) {
        Vec2 d;
        const bool hit = assist.Update(vp, ents, 3, view, 1.0f / 60.0f, &d);
        std::printf("frame %d: hit=%d target=%d delta=(%.2f, %.2f)\n",
                    frame, hit ? 1 : 0, assist.LastTarget(), d.x, d.y);
    }
    return 0;
}
#endif
